// Get the input text
const inputText = $input.first().json.result.content[0].text; // Adjust field name as needed

// Check if it's a simple message (no colons or very short)
const hasStructuredData = inputText.includes(':') && inputText.split('\n').length > 1;

if (!hasStructuredData) {
  // Handle simple messages like "you are not connected to the server"
  return [{
    json: {
      error: true,
      message: inputText.trim(),
      connected: false
    }
  }];
}

// Parse structured server info
const lines = inputText.split('\n');
const result = {
  error: false,
  connected: true
};

lines.forEach(line => {
  // Skip empty lines
  if (line.trim() === '') return;

  // Split on the first colon to separate key and value
  const colonIndex = line.indexOf(':');
  if (colonIndex === -1) return;

  const key = line.substring(0, colonIndex).trim();
  const value = line.substring(colonIndex + 1).trim();

  // Convert key to camelCase and clean it up
  const cleanKey = key
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, '') // Remove special characters
    .replace(/\s+(.)/g, (match, letter) => letter.toUpperCase()) // Convert to camelCase
    .replace(/\s/g, ''); // Remove remaining spaces

  // Try to convert numeric values
  let parsedValue = value;
  if (!isNaN(value) && value !== '') {
    parsedValue = parseFloat(value);
  }

  result[cleanKey] = parsedValue;
});

// Return the formatted JSON
return [{ json: result }];

// Get input text with proper JSON parsing
let text = '';
try {
  const input = $input.first()?.json;

  // Try different possible paths
  if (input?.data) {
    // Parse the JSON string in data field
    const parsedData = JSON.parse(input.data);
    text = parsedData?.result?.content?.[0]?.text || '';
  } else {
    // Fallback to other common paths
    text = input?.body || input?.text || input?.content || '';
  }
} catch (e) {
  return { json: { error: 'Could not parse input data', details: e.message } };
}

if (!text || typeof text !== 'string') {
  return { json: { error: 'No valid text input found', text: text } };
}

// Helper functions
function safeMatch(text, regex) {
  try { return text.match(regex); } catch { return null; }
}
function safeParseInt(value, fallback = null) {
  const parsed = parseInt(value); return isNaN(parsed) ? fallback : parsed;
}
function safeParseFloat(value, fallback = null) {
  const parsed = parseFloat(value); return isNaN(parsed) ? fallback : parsed;
}

// Extract scan info
const scanMatch = safeMatch(text, /Area scan complete \((\d+) block radius from (-?\d+), (-?\d+), (-?\d+)\)/);
const scannedMatch = safeMatch(text, /Scanned: (\d+)\/(\d+) blocks \((\d+\.\d+)%\)/);

// Debug: Let's see what we're working with
const debugInfo = {
  textLength: text.length,
  textPreview: text.substring(0, 200),
  containsMostCommon: text.includes('Most common blocks:'),
  containsInteresting: text.includes('Interesting blocks nearby:')
};

// Extract most common blocks - more flexible approach
const mostCommonBlocks = [];
const mostCommonStart = text.indexOf('Most common blocks:');
const interestingStart = text.indexOf('Interesting blocks nearby:');

if (mostCommonStart !== -1) {
  const endPos = interestingStart !== -1 ? interestingStart : text.length;
  const blocksText = text.substring(mostCommonStart, endPos);

  // Match each block line individually
  const blockMatches = blocksText.matchAll(/([a-z0-9_]+): (\d+) \((\d+\.\d+)%\)/g);
  for (const match of blockMatches) {
    mostCommonBlocks.push({
      block: match[1],
      count: safeParseInt(match[2], 0),
      percentage: safeParseFloat(match[3], 0)
    });
  }
}

// Extract interesting blocks - more flexible approach
const interestingBlocks = [];
let moreCount = 0;

if (interestingStart !== -1) {
  const interestingText = text.substring(interestingStart);

  // Match each interesting block line individually
  const blockMatches = interestingText.matchAll(/([a-z0-9_]+) at \((-?\d+), (-?\d+), (-?\d+)\) - (\d+\.\d+) blocks away/g);
  for (const match of blockMatches) {
    interestingBlocks.push({
      block: match[1],
      position: {
        x: safeParseInt(match[2], 0),
        y: safeParseInt(match[3], 0),
        z: safeParseInt(match[4], 0)
      },
      distance: safeParseFloat(match[5], 0)
    });
  }

  // Check for "and X more"
  const moreMatch = safeMatch(interestingText, /\.\.\. and (\d+) more/);
  if (moreMatch) {
    moreCount = safeParseInt(moreMatch[1], 0);
  }
}

// Build final JSON
const result = {
  scan: {
    radius: scanMatch ? safeParseInt(scanMatch[1]) : null,
    center: scanMatch ? {
      x: safeParseInt(scanMatch[2]),
      y: safeParseInt(scanMatch[3]),
      z: safeParseInt(scanMatch[4])
    } : null,
    scanned: scannedMatch ? safeParseInt(scannedMatch[1]) : null,
    total: scannedMatch ? safeParseInt(scannedMatch[2]) : null,
    percentage: scannedMatch ? safeParseFloat(scannedMatch[3]) : null
  },
  mostCommonBlocks,
  interestingBlocks: {
    blocks: interestingBlocks,
    additionalCount: moreCount
  },
  debug: debugInfo,
  rawTextLength: text.length,
  processingSuccess: true
};

return { json: result };

const inputText =  $input.first().json.result.content[0].text// Adjust path as needed

// Split into sections by double newlines
const sections = inputText.split('\n\n');

// Extract header info
const headerMatch = sections[0].match(/Block search results \(within (\d+) blocks\):/);
const searchRadius = headerMatch ? parseInt(headerMatch[1]) : null;

// Extract total blocks
const totalMatch = inputText.match(/Total blocks found: (\d+)/);
const totalBlocks = totalMatch ? parseInt(totalMatch[1]) : 0;

// Parse block types
const blockTypes = {};

sections.slice(1, -1).forEach(section => {
  const lines = section.trim().split('\n');
  const typeMatch = lines[0].match(/^(\w+): (\d+) found$/);

  if (typeMatch) {
    const blockType = typeMatch[1];
    const count = parseInt(typeMatch[2]);

    const blocks = [];

    // Parse each block entry
    lines.slice(1).forEach(line => {
      const blockMatch = line.match(/^\s+\d+\.\s+\((-?\d+),\s*(-?\d+),\s*(-?\d+)\)\s+-\s+([\d.]+)\s+blocks$/);
      if (blockMatch) {
        blocks.push({
          x: parseInt(blockMatch[1]),
          y: parseInt(blockMatch[2]),
          z: parseInt(blockMatch[3]),
          distance: parseFloat(blockMatch[4])
        });
      }
    });

    blockTypes[blockType] = {
      count: count,
      blocks: blocks
    };
  }
});

const result = {
  searchRadius: searchRadius,
  totalBlocks: totalBlocks,
  blockTypes: blockTypes
};

return [{ json: result }];

const inputText =  $input.first().json.result.content[0].text;// Adjust path as needed

// Extract header info
const headerMatch = inputText.match(/Structure analysis \((\d+) block radius\):/);
const analysisRadius = headerMatch ? parseInt(headerMatch[1]) : null;

// Split into structure sections
const sections = inputText.split(/\n\n/).filter(section => section.trim() && !section.includes('Structure analysis'));

const structures = [];

sections.forEach(section => {
  const lines = section.trim().split('\n');

  if (lines.length >= 6) {
    // Extract structure number and name
    const nameMatch = lines[0].match(/^(\d+)\.\s+(.+)$/);

    // Extract material
    const materialMatch = lines[1].match(/^\s+Material:\s+(.+)$/);

    // Extract center coordinates
    const centerMatch = lines[2].match(/^\s+Center:\s+\((-?\d+),\s*(-?\d+),\s*(-?\d+)\)$/);

    // Extract size
    const sizeMatch = lines[3].match(/^\s+Size:\s+(\d+)×(\d+)×(\d+)$/);

    // Extract blocks and density
    const blocksMatch = lines[4].match(/^\s+Blocks:\s+(\d+),\s+Density:\s+([\d.]+)$/);

    // Extract distance
    const distanceMatch = lines[5].match(/^\s+Distance:\s+([\d.]+)\s+blocks$/);

    if (nameMatch && materialMatch && centerMatch && sizeMatch && blocksMatch && distanceMatch) {
      structures.push({
        id: parseInt(nameMatch[1]),
        name: nameMatch[2],
        material: materialMatch[1],
        center: {
          x: parseInt(centerMatch[1]),
          y: parseInt(centerMatch[2]),
          z: parseInt(centerMatch[3])
        },
        size: {
          width: parseInt(sizeMatch[1]),
          height: parseInt(sizeMatch[2]),
          depth: parseInt(sizeMatch[3])
        },
        blocks: parseInt(blocksMatch[1]),
        density: parseFloat(blocksMatch[2]),
        distance: parseFloat(distanceMatch[1])
      });
    }
  }
});

const result = {
  analysisRadius: analysisRadius,
  structureCount: structures.length,
  structures: structures
};

return [{ json: result }];

const inputText = $input.first().json.result.content[0].text; // Adjust path as needed

// Extract header info
const headerMatch = inputText.match(/Safe location search results \((\d+) block radius\):/);
const searchRadius = headerMatch ? parseInt(headerMatch[1]) : null;

// Split into location sections
const sections = inputText.split(/\n\n/).filter(section => section.trim() && !section.includes('Safe location search'));

const locations = [];

sections.forEach(section => {
  const lines = section.trim().split('\n');

  if (lines.length >= 5) {
    // Extract location number, status, and coordinates
    const locationMatch = lines[0].match(/^(\d+)\.\s+(✅|❌)\s+Location:\s+\((-?\d+),\s*(-?\d+),\s*(-?\d+)\)$/);

    // Extract distance
    const distanceMatch = lines[1].match(/^\s+Distance:\s+([\d.]+)\s+blocks$/);

    // Extract flat area
    const flatAreaMatch = lines[2].match(/^\s+Flat area:\s+(\d+)\s+blocks$/);

    // Extract safety status
    const safetyMatch = lines[3].match(/^\s+Safety:\s+(.+)$/);

    // Extract notes
    const notesMatch = lines[4].match(/^\s+Notes:\s+(.+)$/);

    if (locationMatch && distanceMatch && flatAreaMatch && safetyMatch && notesMatch) {
      locations.push({
        id: parseInt(locationMatch[1]),
        status: locationMatch[2] === '✅' ? 'safe' : 'unsafe',
        coordinates: {
          x: parseInt(locationMatch[3]),
          y: parseInt(locationMatch[4]),
          z: parseInt(locationMatch[5])
        },
        distance: parseFloat(distanceMatch[1]),
        flatArea: parseInt(flatAreaMatch[1]),
        safety: safetyMatch[1],
        notes: notesMatch[1] === 'none' ? null : notesMatch[1]
      });
    }
  }
});

const result = {
  searchRadius: searchRadius,
  locationCount: locations.length,
  safeLocations: locations.filter(loc => loc.status === 'safe').length,
  unsafeLocations: locations.filter(loc => loc.status === 'unsafe').length,
  locations: locations
};

return [{ json: result }];

// Get input text with flexible path handling
let text = '';
try {
  const input = $input.first()?.json;

  // Try multiple possible paths
  if (input?.result?.content?.[0]?.text) {
    text = input.result.content[0].text;
  } else if (input?.data) {
    // If data is a JSON string, parse it
    if (typeof input.data === 'string') {
      const parsedData = JSON.parse(input.data);
      text = parsedData?.result?.content?.[0]?.text || '';
    } else {
      text = input.data?.result?.content?.[0]?.text || '';
    }
  } else {
    // Fallback paths
    text = input?.body || input?.text || input?.content || '';
  }
} catch (e) {
  return { json: { error: 'Could not parse input data', details: e.message } };
}

if (!text || typeof text !== 'string') {
  // Debug: show what we actually received
  const debugInput = $input.first()?.json;
  return { 
    json: { 
      error: 'No valid text input found', 
      text: text,
      inputStructure: Object.keys(debugInput || {}),
      fullInput: debugInput
    } 
  };
}

// Helper functions
function safeMatch(text, regex) {
  try { return text.match(regex); } catch { return null; }
}
function safeParseInt(value, fallback = null) {
  const parsed = parseInt(value); return isNaN(parsed) ? fallback : parsed;
}

// Extract coordinates from title
const coordMatch = safeMatch(text, /Biome Information for \((-?\d+), (-?\d+)\)/);

// Extract biome information
const biomeMatch = safeMatch(text, /🌍 Biome: ([a-z_]+) \(ID: (\d+)\)/);
const tempMatch = safeMatch(text, /🌡️\s+Temperature: ([^\n]+)/);
const rainMatch = safeMatch(text, /🌧️\s+Rainfall: ([^\n]+)/);
const featuresMatch = safeMatch(text, /🏞️\s+Features: ([^\n]+)/);

// Extract weather and time
const weatherMatch = safeMatch(text, /Current weather: [^a-zA-Z]*([^\n]+)/);
const timeMatch = safeMatch(text, /🕐 Time: ([^\n]+)/);

// Parse time details if available
let timeDetails = null;
if (timeMatch && timeMatch[1]) {
  const timeStr = timeMatch[1].trim();
  const timeParseMatch = safeMatch(timeStr, /([A-Za-z]+)\s*\((\d+):(\d+)\)/);
  if (timeParseMatch) {
    timeDetails = {
      period: timeParseMatch[1],
      hour: safeParseInt(timeParseMatch[2]),
      minute: safeParseInt(timeParseMatch[3]),
      formatted: timeStr
    };
  } else {
    timeDetails = { formatted: timeStr };
  }
}

// Parse features into array
let features = [];
if (featuresMatch && featuresMatch[1]) {
  features = featuresMatch[1].split(',').map(f => f.trim()).filter(f => f);
}

// Build result
const result = {
  location: {
    x: coordMatch ? safeParseInt(coordMatch[1]) : null,
    z: coordMatch ? safeParseInt(coordMatch[2]) : null
  },
  biome: {
    name: biomeMatch ? biomeMatch[1] : null,
    id: biomeMatch ? safeParseInt(biomeMatch[2]) : null,
    temperature: tempMatch ? tempMatch[1].trim() : null,
    rainfall: rainMatch ? rainMatch[1].trim() : null,
    features: features
  },
  weather: weatherMatch ? weatherMatch[1].trim() : null,
  time: timeDetails,
  rawTextLength: text.length,
  processingSuccess: true
};

return { json: result };

// Get input text
let text = '';
try {
  const input = $input.first()?.json;
  text = input?.result?.content?.[0]?.text || '';
} catch (e) {
  return { json: { error: 'Could not parse input data', details: e.message } };
}

if (!text || typeof text !== 'string') {
  return { json: { error: 'No valid text input found', text: text } };
}

// Helper functions
function safeMatch(text, regex) {
  try { return text.match(regex); } catch { return null; }
}
function safeParseInt(value, fallback = null) {
  const parsed = parseInt(value); return isNaN(parsed) ? fallback : parsed;
}
function safeParseFloat(value, fallback = null) {
  const parsed = parseFloat(value); return isNaN(parsed) ? fallback : parsed;
}

// Extract number of threats and radius
const headerMatch = safeMatch(text, /Found (\d+) potential threats within (\d+) blocks:/);
const threatCount = headerMatch ? safeParseInt(headerMatch[1]) : null;
const radius = headerMatch ? safeParseInt(headerMatch[2]) : null;

// Extract each threat block
const threatRegex = /(\d+)\.\s+🟢 Hostile Mob: ([a-z_]+)\s+Location: \((-?\d+), (-?\d+), (-?\d+)\)\s+Distance: ([\d.]+) blocks\s+Threat Level: ([A-Z]+)/g;
let threats = [];
let match;
while ((match = threatRegex.exec(text)) !== null) {
  threats.push({
    index: safeParseInt(match[1]),
    mob: match[2],
    location: {
      x: safeParseInt(match[3]),
      y: safeParseInt(match[4]),
      z: safeParseInt(match[5])
    },
    distance: safeParseFloat(match[6]),
    threatLevel: match[7]
  });
}

// Build result
const result = {
  reportType: "danger_detection",
  threatCount,
  radius,
  threats,
  rawTextLength: text.length,
  processingSuccess: true
};

return { json: result };

